const items = $input.all();
const results = [];

const sqlEscape = (str) => {
  if (!str) return '';
  return String(str).replace(/'/g, "''");
};

for (const item of items) {
  const data = item.json;
  if (!data.id) continue;

  const email = data.email_address || `${data.id.toLowerCase()}@linkedin.user`;
  const company = data.company || '';
  const domain = company ? company.toLowerCase().replace(/[^a-z0-9]/g, '') + '.com' : null;

  results.push({
    json: {
      connection_id: data.id,
      first_name: data.first_name || '',
      last_name: data.last_name || '',
      email: email,
      company: company,
      domain: domain,
      position: data.position || '',
      profile_url: data.profile_url || '',
      connected_at: data.connected_at || new Date().toISOString(),
      sql_connection_id: sqlEscape(data.id),
      sql_first_name: sqlEscape(data.first_name || ''),
      sql_last_name: sqlEscape(data.last_name || ''),
      sql_email: sqlEscape(email),
      sql_company: sqlEscape(company),
      sql_domain: domain ? sqlEscape(domain) : null,
      sql_position: sqlEscape(data.position || ''),
      sql_profile_url: sqlEscape(data.profile_url || '')
    }
  });
}

return results;
